const traits = $('UI Set').first().json.traits;
const agent_response = $input.first().json.text;

const traitKeys = [
  "activity",
  "affection_need",
  "maintenance_willingness",
  "noise_tolerance",
  "time_away"
];

const updatedTraits = JSON.parse(JSON.stringify(traits));

let parsed = null;
try {
  parsed = JSON.parse(agent_response);
} catch (e) {
  parsed = null;
}

// default changed message fallback
let changed = null;

// CASE 1: structured output
if (parsed && parsed.traits) {

  // take changed directly if provided
  if (parsed.changed) {
    changed = parsed.changed;
  }

  for (const key of traitKeys) {

    if (parsed.traits[key] !== undefined) {
      const v = parsed.traits[key];

      if (typeof v === "number" && v >= 1 && v <= 7) {
        updatedTraits[key].value = v;
      }
    }

    if (parsed.confidence && parsed.confidence[key] !== undefined) {
      const c = parsed.confidence[key];

      if (typeof c === "number" && c >= 0 && c <= 1) {
        updatedTraits[key].confidence = c;
      }
    }
  }
}

// CASE 2: fallback (no changed available → optional)
else {
  for (const key of traitKeys) {
    const regex = new RegExp(
      `${key}\\s*[:=]\\s*(-?\\d+)`,
      'i'
    );

    const match = agent_response.match(regex);

    if (match) {
      const value = parseInt(match[1]);

      if (value >= 1 && value <= 7) {
        updatedTraits[key].value = value;
        changed = `Updated ${key} based on extracted value ${value}`;
      }
    }
  }
}

return [ 
  { 
    json: { 
      traits: updatedTraits, 
      changed: changed 
    } 
  } 
];

const traits = $input.first().json.traits;

const traitKeys = [
  "activity",
  "affection_need",
  "maintenance_willingness",
  "noise_tolerance",
  "time_away"
];

let isComplete = true;

for (const key of traitKeys) {
  const t = traits[key];

  // must exist
  if (!t) {
    isComplete = false;
    break;
  }

  // value must be set
  if (t.value === -1 || t.value === null || t.value === undefined) {
    isComplete = false;
    break;
  }

  // confidence must be high enough
  if (t.confidence === undefined || t.confidence < 0.7) {
    isComplete = false;
    break;
  }
}

return [
  {
    json: {
      isComplete
    }
  }
];

